package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class FastMath_signum_TriageGen0Test {

    @Test
    public void testSignumWithPositiveValue() {
        assertEquals(1.0, FastMath.signum(1.0), 0.0);
        assertEquals(1.0, FastMath.signum(Double.MAX_VALUE), 0.0);
        assertEquals(1.0, FastMath.signum(0.00000000001), 0.0);
    }

    @Test
    public void testSignumWithNegativeValue() {
        assertEquals(-1.0, FastMath.signum(-1.0), 0.0);
        assertEquals(-1.0, FastMath.signum(-Double.MAX_VALUE), 0.0);
        assertEquals(-1.0, FastMath.signum(-0.00000000001), 0.0);
    }

    @Test
    public void testSignumWithZero() {
        assertEquals(0.0, FastMath.signum(0.0), 0.0);
        assertEquals(0.0, FastMath.signum(-0.0), 0.0);
    }

    @Test
    public void testSignumWithNaN() {
        assertEquals(Double.NaN, FastMath.signum(Double.NaN), 0.0);
    }
}
